// DOM Controller
// All DOM releated functions

import { constructFromSymbol } from "date-fns/constants";
import { readProjects, saveNewTodo, readToDos, saveNewProject, saveEditedToDo, deleteToDo } from "./storageController";
import { ToDoCard } from "./todo-card";
import { Checkbox } from "./checkbox";

/* Event Listeners */
// New ToDo Button
const newTodo = document.querySelector('#new-todo')
newTodo.addEventListener('click',newTodoDialog);
const dialogToDo = document.querySelector('#new-todo-dialog');
const formTodo = dialogToDo.querySelectorAll('input, textarea');
const confirmBtn = dialogToDo.querySelector('#confirmBtn');
// "Cancel" button closes the dialog without submitting because of [formmethod="dialog"], triggering a close event.
dialogToDo.addEventListener("close", (e) => {

    if((dialogToDo.returnValue !== '' && dialogToDo.returnValue !== 'cancel') && (JSON.parse(dialogToDo.returnValue).title !== '')){
        saveNewTodo(dialogToDo.returnValue);
        displayToDos();
    }
  });

// Prevent the "confirm" button from the default behavior of submitting the form, and close the dialog with the `close()` method, which triggers the "close" event.
confirmBtn.addEventListener("click", (event) => {
event.preventDefault(); // We don't want to submit this fake form

const title = dialogToDo.querySelector('#title');
const group = dialogToDo.querySelector('#group');
const date = dialogToDo.querySelector('#date');
const priority = dialogToDo.querySelector('#priority');
const desc = dialogToDo.querySelector('#desc');

const todo = new ToDoCard(title.value, group.value, date.value, priority.value, desc.value);

dialogToDo.close(JSON.stringify(todo)); // Have to send the select box value here.
});
// New Project Button

const addProjectBtn = dialogToDo.querySelector('#add-project');
addProjectBtn.addEventListener('click', (e) =>{

    const newProject = prompt('Enter new project name:');

    if(newProject !== null) saveNewProject(newProject);

    updateProjectOptions();
    displayProjectFitlers();


});

// Filter ToDos
const filterAll = document.querySelector('#filter-all');
const filterHigh = document.querySelector('#filter-high');
const filterMedium = document.querySelector('#filter-medium');
const filterLow = document.querySelector('#filter-low');
const filters = document.querySelector('.filters');
filterAll.addEventListener('click', (e)=>{displayToDos()});
filterHigh.addEventListener('click', (e)=>{displayToDos('priority', 'high')});
filterMedium.addEventListener('click', (e)=>{displayToDos('priority', 'medium')});
filterLow.addEventListener('click', (e)=>{displayToDos('priority', 'low')});

// Expand ToDos
const expToDoConfirmBtn = document.querySelector('#saveBtn');
expToDoConfirmBtn.addEventListener('click', (e)=>{
    e.preventDefault();

    // We only care about textarea notes and checkboxes
    const dialog = document.querySelector('#todo-expanded');
    
    const title = dialog.querySelector('.todo-title');
    const group = dialog.querySelector('.todo-project');
    const date = dialog.querySelector('.todo-date');
    const priority = dialog.querySelector('.todo-priority');
    const desc = dialog.querySelector('.todo-desc');

    const todos = readToDos();

    const editedToDoIndex = todos.findIndex((element) => {
        return (
            element.title.toLowerCase() === title.textContent.toLowerCase() &&
            element.group.toLowerCase() === group.textContent.toLowerCase().slice(9) &&
            element.date.toLowerCase() === date.textContent.toLowerCase().slice(10) &&
            element.priority.toLowerCase() === priority.textContent.toLowerCase().slice(10) &&
            element.desc.toLowerCase() === desc.textContent.toLowerCase().slice(13)
        );
    });

    const notes = dialog.querySelector('textarea').value
    const checkboxesList = dialog.querySelectorAll('li'); // Containes checkbox and label

    const toSaveCheckboxes = [];

    checkboxesList.forEach(element => {
        const checkbox = element.querySelector('input');
        const label = element.querySelector('label');

        const checkboxObj = new Checkbox(label.textContent, checkbox.checked);

        toSaveCheckboxes.push(checkboxObj);
        
    });

    saveEditedToDo(editedToDoIndex, notes, toSaveCheckboxes)

    dialog.close('save');

});

const ExpToDoDialog = document.querySelector('#todo-expanded');
ExpToDoDialog.addEventListener('close', (e)=>{

    if(ExpToDoDialog.returnValue === 'delete'){
        //Delete To Do

        // We only care about textarea notes and checkboxes
        const dialog = document.querySelector('#todo-expanded');
        
        const title = dialog.querySelector('.todo-title');
        const group = dialog.querySelector('.todo-project');
        const date = dialog.querySelector('.todo-date');
        const priority = dialog.querySelector('.todo-priority');
        const desc = dialog.querySelector('.todo-desc');

        const todos = readToDos();

        const toDoDeleteIndex = todos.findIndex((element) => {
            return (
                element.title.toLowerCase() === title.textContent.toLowerCase() &&
                element.group.toLowerCase() === group.textContent.toLowerCase().slice(9) &&
                element.date.toLowerCase() === date.textContent.toLowerCase().slice(10) &&
                element.priority.toLowerCase() === priority.textContent.toLowerCase().slice(10) &&
                element.desc.toLowerCase() === desc.textContent.toLowerCase().slice(13)
            );
        });

        deleteToDo(toDoDeleteIndex);

        displayToDos();
    }

});


export function updateProjectOptions(){
    const groupSelector = document.querySelector('#group');

    const projectsOld = groupSelector.querySelectorAll('option');
    projectsOld.forEach(element => {
        groupSelector.removeChild(element);
    });

    const projectsList = readProjects();

    projectsList.forEach(element => {
        const option = document.createElement('option');
        option.textContent = element.name;
        option.setAttribute('value', element.name.toLowerCase());

        groupSelector.appendChild(option);
    });
}

export function newTodoDialog(){

    updateProjectOptions();

    dialogToDo.showModal();

}

export function displayToDos(type, filterBy){
    const todos = readToDos();
    let filteredToDos
    // Clear Board before we display more
    clearBoard();

    const mainContent = document.querySelector('main');

    if(type !== undefined){
        
        if(type === 'priority'){
            filteredToDos = todos.filter((todo)=>{return todo.priority === filterBy});
        }else if(type === 'group'){
            filteredToDos = todos.filter((todo)=>{return todo.group.toLowerCase() === filterBy.toLowerCase()});
        }

    }else{
        filteredToDos = todos;
    }

    let index = 0;

    filteredToDos.forEach(todoCard => {

        const card = document.createElement('div');
        card.classList.add('project-card');
        card.dataset.index = index++; // Save index and increment for next

        const title = document.createElement('h2');
        title.classList.add('project-title')
        title.textContent = todoCard.title;

        const group = document.createElement('p');
        group.classList.add('project-group');
        group.textContent = `Project: ${todoCard.group}`;

        const button = document.createElement('button');
        button.setAttribute('type', 'button');
        button.classList.add('project-edit');
        button.addEventListener('click', (e)=>{
            expandToDo(todos[card.dataset.index]);
        })

        // Crear el elemento SVG
        const svgNS = "http://www.w3.org/2000/svg"; // Namespace para SVG
        const svg = document.createElementNS(svgNS, "svg");

        // Añadir atributos al SVG
        svg.setAttribute("xmlns", svgNS);
        svg.setAttribute("viewBox", "0 0 24 24");

        // Crear el elemento <title>
        const titleSVG = document.createElementNS(svgNS, "title");
        titleSVG.textContent = "text-box-edit-outline";
        svg.appendChild(titleSVG);

        // Crear el elemento <path> con el atributo "d"
        const path = document.createElementNS(svgNS, "path");
        path.setAttribute(
            "d",
            "M10 21H5C3.89 21 3 20.11 3 19V5C3 3.89 3.89 3 5 3H19C20.11 3 21 3.89 21 5V10.33C20.7 10.21 20.37 10.14 20.04 10.14C19.67 10.14 19.32 10.22 19 10.37V5H5V19H10.11L10 19.11V21M7 9H17V7H7V9M7 17H12.11L14 15.12V15H7V17M7 13H16.12L17 12.12V11H7V13M21.7 13.58L20.42 12.3C20.21 12.09 19.86 12.09 19.65 12.3L18.65 13.3L20.7 15.35L21.7 14.35C21.91 14.14 21.91 13.79 21.7 13.58M12 22H14.06L20.11 15.93L18.06 13.88L12 19.94V22Z"
            );

        // Añadir el <path> al SVG
        svg.appendChild(path);

        button.appendChild(svg);

        const date = document.createElement('p');
        date.classList.add('project-date');
        date.textContent = `Due Date: ${todoCard.date}`;

        const priority = document.createElement('p');
        priority.classList.add('project-priority');
        priority.classList.add(todoCard.priority === 'high' ? 'high' : todoCard.priority === 'medium' ? 'medium' : 'low');
        
        priority.textContent = `Project: ${todoCard.priority}`;

        const desc = document.createElement('p');
        desc.classList.add('project-desc');
        desc.textContent = `Project: ${todoCard.desc}`;


        card.appendChild(title);
        card.appendChild(group);
        card.appendChild(button);
        card.appendChild(date);
        card.appendChild(priority);
        card.appendChild(desc);

        mainContent.appendChild(card);

    });
}

export function clearBoard(){

    const mainContent = document.querySelector('main');
    const todoCards = document.querySelectorAll('main > div');

    todoCards.forEach(element => {
        mainContent.removeChild(element);
    });
    

}

export function clearProjectFilters(){

    const filtersOld = filters.querySelectorAll('button:nth-child(n + 6)')

    filtersOld.forEach(element => {
        filters.removeChild(element);
    });

}

export function displayProjectFitlers(){
    
    const projects = readProjects(); // lo devuelve como objeto

    clearProjectFilters();

    projects.forEach(element => {

        const buttonProject = document.createElement('button');
        buttonProject.setAttribute('type', 'button');
        buttonProject.dataset.project = element.name;
        buttonProject.textContent = element.name;


        buttonProject.addEventListener('click', (e)=>{displayToDos('group', element.name)});

        filters.appendChild(buttonProject);

    });
}

function expandToDo(toDoObj){

    console.log(toDoObj)
    console.log(toDoObj.checkboxes)
    
    const dialog = document.querySelector('#todo-expanded');

    const title = dialog.querySelector('.todo-title');
    const project = dialog.querySelector('.todo-project');
    const date = dialog.querySelector('.todo-date');
    const priority = dialog.querySelector('.todo-priority');
    const desc = dialog.querySelector('.todo-desc');
    
    title.textContent = toDoObj.title;
    project.textContent = 'Project: ' + toDoObj.group;
    date.textContent = 'Due date: ' + toDoObj.date;
    priority.textContent = 'Priority: ' + toDoObj.priority;
    desc.textContent = 'Description: ' + toDoObj.desc;

    const textarea = dialog.querySelector('textarea');
    console.log(toDoObj.notes)
    textarea.value = toDoObj.notes
    console.log(textarea.value)

    const addCheckboxBtn = dialog.querySelector('button[type="button"]');
    addCheckboxBtn.addEventListener('click', addCheckbox);

    const checkboxList = dialog.querySelector('ul');

    // delete old checkboxes
    const oldCheckboxes = checkboxList.querySelectorAll('li');
    oldCheckboxes.forEach(element => {
        checkboxList.removeChild(element)
    });

    let index = 0;

    toDoObj.checkboxes.forEach(element => {
        const li = document.createElement('li');

        const checkbox = document.createElement('input');
        checkbox.setAttribute('type', 'checkbox');
        checkbox.setAttribute('id', 'checkbox'+index);
        checkbox.dataset.index = index;
        if (!element.status) {
            checkbox.removeAttribute("checked");
        } else {
            checkbox.setAttribute("checked", "true");
        }
        


        const label = document.createElement('label');
        label.setAttribute('for', 'checkbox'+index++);
        label.textContent = element.name;

        li.appendChild(checkbox);
        li.appendChild(label);
        checkboxList.appendChild(li);

    });

    dialog.showModal();

}

function addCheckbox(){

    const checkboxList = document.querySelector('.checkbox-list');
    const li = document.createElement('li');

    const lastCheckbox = document.querySelector('input[type="checkbox"');
    let index = lastCheckbox !== null ? parseInt(lastCheckbox.dataset.index)+1 : 0;


    const checkbox = document.createElement('input');
    checkbox.setAttribute('type', 'checkbox');
    checkbox.setAttribute('id', 'checkbox' + index);
    checkbox.dataset.index = index;


    const label = document.createElement('label');
    label.setAttribute('for', 'checkbox'+index);
    const text = prompt('Enter text of checkbox:');
    label.textContent = text !== null ? text : '';

    li.appendChild(checkbox);
    li.appendChild(label);

    checkboxList.appendChild(li);

}