// Storage Controller
// all functions that affect Local Storage (CRUD)

export function storageAvailable(type) {
    let storage;
    try {
      storage = window[type];
      const x = "__storage_test__";
      storage.setItem(x, x);
      storage.removeItem(x);
      return true;
    } catch (e) {
      return (
        e instanceof DOMException &&
        e.name === "QuotaExceededError" &&
        // acknowledge QuotaExceededError only if there's something already stored
        storage &&
        storage.length !== 0
      );
    }
  }

export function populateEmptyStorage(){
    if(!localStorage.getItem('projects')){
        localStorage.setItem('projects', '[]');
    }
    if(!localStorage.getItem('todos')){
        localStorage.setItem('todos', '[]');
    }
}


export function readProjects(){
    return JSON.parse(localStorage.getItem('projects'));
}

export function saveNewProject(projectName){

    const newProject = {
        name: projectName
    }

    const currentProjects = readProjects();
    currentProjects.push(newProject);
    localStorage.setItem('projects', JSON.stringify(currentProjects));

}

export function readToDos(){
    return JSON.parse(localStorage.getItem('todos'));
}

export function saveNewTodo(toDoString){
    const todos = JSON.parse(localStorage.getItem('todos'));

    todos.push(JSON.parse(toDoString));

    localStorage.setItem('todos', JSON.stringify(todos))

}

export function saveEditedToDo(indexToDo, notes, checkboxList){
    
    const toDos = readToDos();

    toDos[indexToDo].notes = notes;
    toDos[indexToDo].checkboxes = checkboxList;

    localStorage.setItem('todos', JSON.stringify(toDos));

}

export function deleteToDo(index){
    const todos = readToDos();

    todos.splice(index, 1);

    localStorage.setItem('todos', JSON.stringify(todos));

}

